import{_ as e,o as i,c as r,ag as d}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"12.3 多媒体数据与图像容量 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/03-多媒体与图像容量.md","filePath":"12-数学与多媒体/03-多媒体与图像容量.md"}'),a={name:"12-数学与多媒体/03-多媒体与图像容量.md"};function o(l,t,n,s,h,p){return i(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_12-3-多媒体数据与图像容量-★★★" tabindex="-1">12.3 多媒体数据与图像容量 ★★★ <a class="header-anchor" href="#_12-3-多媒体数据与图像容量-★★★" aria-label="Permalink to &quot;12.3 多媒体数据与图像容量 ★★★&quot;">​</a></h1><p>现实中的声音和图像多是连续信号，计算机要经过三步：</p><ol><li><strong>采样</strong>：在时间或空间上取点；</li><li><strong>量化</strong>：把每个样本映射为有限等级；</li><li><strong>编码</strong>：用二进制表示量化结果。</li></ol><p>质量与数据量的基本矛盾：采样越密、量化位数越多，通常越接近原信号，但存储与传输开销越大。</p><p>所有原始容量题都可用同一个思路：</p><p><strong>样本个数 × 每个样本的 bit 数 ÷ 8 = Byte 数</strong></p><p>图像的样本是像素，音频的样本是每个声道每次采样值，视频则是在时间上连续出现的图像帧。</p><p>单位必须统一：</p><ul><li><code>1 B=8 bit</code>；</li><li><code>1 KiB=1024 B</code>，<code>1 MiB=1024 KiB=2^20 B</code>；</li><li><strong>卷面对齐</strong>：软考卷面里的 <strong>MB 通常也按 1024 换算</strong>，即 <code>1 MB=1024 KB=2²⁰ B</code>——数值上与本课的 MiB 完全一致，只是叫法不同，做题直接用 1024 换即可，不必纠结 MB/MiB 的拼写区分；</li><li>存储题若明确使用 KB/MB 的十进制定义，则按题面；未说明的传统软考计算通常按 1024 换算；</li><li>传输速率的 kb/s、Mb/s 常按 1000 进位，仍以题面为准。</li></ul><p><strong>应试动作</strong>：计算式最后写出单位。先得到 bit，再除以 8 变 Byte；只有题目要求 KiB/MiB 时才继续除以 1024。</p><hr><h2 id="第七节-图像容量与分辨率-★★★" tabindex="-1">第七节 图像容量与分辨率 ★★★ <a class="header-anchor" href="#第七节-图像容量与分辨率-★★★" aria-label="Permalink to &quot;第七节 图像容量与分辨率 ★★★&quot;">​</a></h2><h3 id="_7-1-位图容量公式" tabindex="-1">7.1 位图容量公式 <a class="header-anchor" href="#_7-1-位图容量公式" aria-label="Permalink to &quot;7.1 位图容量公式&quot;">​</a></h3><p>未压缩位图容量：</p><p><strong>容量(bit)=水平像素×垂直像素×每像素位数</strong></p><p><strong>容量(Byte)=水平像素×垂直像素×位深÷8</strong></p><p>例：一幅 <code>1024×768</code>、24 bit 真彩色图像：</p><ol><li>像素数=<code>1024×768=786432</code>；</li><li>bit 数=<code>786432×24=18874368 bit</code>；</li><li>Byte 数=<code>18874368/8=2359296 B</code>；</li><li>MiB=<code>2359296/2^20=2.25 MiB</code>。</li></ol><p>第二种方法：24 bit=3 B/像素，直接算 <code>1024×768×3=2359296 B=2.25 MiB</code>，一致。</p><p><strong>反例前置</strong>：24 bit 不是 24 Byte。位深以 bit 表示，每像素 24 bit=3 Byte，漏除以 8 会把容量放大 8 倍。</p><h3 id="_7-2-颜色数与位深" tabindex="-1">7.2 颜色数与位深 <a class="header-anchor" href="#_7-2-颜色数与位深" aria-label="Permalink to &quot;7.2 颜色数与位深&quot;">​</a></h3><p>b bit 最多表示：</p><p><strong>颜色数 = 2^b</strong></p><p>反过来，要表示 N 种颜色，至少需要：</p><p><strong>b=⌈log2N⌉ bit</strong></p><p>常见对应：</p><table tabindex="0"><thead><tr><th style="text-align:right;">位深</th><th style="text-align:right;">最多颜色数</th></tr></thead><tbody><tr><td style="text-align:right;">1 bit</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">4 bit</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">8 bit</td><td style="text-align:right;">256</td></tr><tr><td style="text-align:right;">16 bit</td><td style="text-align:right;">65536</td></tr><tr><td style="text-align:right;">24 bit</td><td style="text-align:right;">2^24≈1677 万</td></tr></tbody></table><p>例：至少表示 300 种颜色。8 bit 只能表示 256 种，不够；9 bit 可表示 512 种，因此至少 9 bit。</p><h3 id="_7-3-像素分辨率与-dpi" tabindex="-1">7.3 像素分辨率与 DPI <a class="header-anchor" href="#_7-3-像素分辨率与-dpi" aria-label="Permalink to &quot;7.3 像素分辨率与 DPI&quot;">​</a></h3><ul><li><code>1920×1080</code>：数字图像的像素尺寸；</li><li>DPI/PPI：每英寸点数/像素数，常用于打印或显示密度；</li><li>打印尺寸（英寸）= 像素数 / PPI。</li></ul><p>例：一幅 3000×2400 像素的图片按 300 PPI 打印，尺寸为 <code>3000/300=10</code> 英寸 × <code>2400/300=8</code> 英寸。</p><p><strong>反例</strong>：只改图片元数据中的 DPI、不改变像素数，通常不会改变未压缩像素数据量；容量公式仍看像素总数和位深。</p><h3 id="_7-4-位图与矢量图" tabindex="-1">7.4 位图与矢量图 <a class="header-anchor" href="#_7-4-位图与矢量图" aria-label="Permalink to &quot;7.4 位图与矢量图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>位图（Raster/Bitmap）</th><th>矢量图（Vector）</th></tr></thead><tbody><tr><td>表示</td><td>像素阵列</td><td>几何对象与参数</td></tr><tr><td>放大</td><td>会出现锯齿/像素化</td><td>可无级缩放</td></tr><tr><td>擅长</td><td>照片、复杂纹理</td><td>图标、工程图、字体</td></tr><tr><td>容量影响</td><td>分辨率、位深</td><td>对象数量与复杂度</td></tr></tbody></table><p><strong>应试动作</strong>：图像容量先写“宽×高×位深÷8”；颜色数用 2^b；打印题用像素÷PPI。</p><hr>',36)])])}const b=e(a,[["render",o]]);export{c as __pageData,b as default};
